
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='keri-teacher-calendar-v1';
const defaults={version:1,termStart:'2026-08-31',classes:[{id:'c1',name:'高一 101',subject:'物理',slots:[{day:1,time:'09:10'},{day:3,time:'10:10'},{day:5,time:'13:10'}]},{id:'c2',name:'高一 102',subject:'物理',slots:[{day:2,time:'10:10'},{day:3,time:'14:10'},{day:5,time:'09:10'}]},{id:'c3',name:'高二 201',subject:'物理',slots:[{day:1,time:'11:10'},{day:2,time:'13:10'},{day:4,time:'09:10'},{day:4,time:'10:10'}]}],exams:[{name:'第一次段考',date:'2026-10-14',end:'2026-10-15'},{name:'第二次段考',date:'2026-11-25',end:'2026-11-26'},{name:'第三次段考',date:'2027-01-13',end:'2027-01-14'}],events:[{id:'h1',date:'2026-09-25',title:'中秋節',type:'off',classId:'all'},{id:'h2',date:'2026-09-28',title:'教師節',type:'off',classId:'all'},{id:'h3',date:'2026-10-09',title:'國慶日補假',type:'off',classId:'all'},{id:'h4',date:'2026-10-10',title:'國慶日',type:'off',classId:'all'},{id:'h5',date:'2026-10-25',title:'臺灣光復暨金門古寧頭大捷紀念日',type:'off',classId:'all'},{id:'h6',date:'2026-10-26',title:'光復紀念日補假',type:'off',classId:'all'},{id:'h7',date:'2026-12-25',title:'行憲紀念日',type:'off',classId:'all'},{id:'h8',date:'2027-01-01',title:'元旦',type:'off',classId:'all'},{id:'s1',date:'2026-10-16',title:'運動會・示範',type:'off',classId:'all'},{id:'s2',date:'2026-10-19',title:'運動會補假・示範',type:'off',classId:'all'}],notes:{}};
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s&&s>='2020-01-01'&&s<='2100-12-31'}
const validTime=s=>typeof s==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(s);
function validate(x){if(!x||x.version!==1||!validDate(x.termStart)||!Array.isArray(x.classes)||x.classes.length!==3||!Array.isArray(x.exams)||x.exams.length!==3||!Array.isArray(x.events)||x.events.length>2000||!x.notes||typeof x.notes!=='object'||Array.isArray(x.notes))return false;const ids=x.classes.map(c=>c.id);if(new Set(ids).size!==3||!ids.every(id=>/^c[123]$/.test(id)))return false;const short=s=>typeof s==='string'&&s.trim().length>0&&s.length<=100;return x.classes.every(c=>short(c.name)&&short(c.subject)&&Array.isArray(c.slots)&&c.slots.length<=50&&c.slots.every(s=>Number.isInteger(s.day)&&s.day>=0&&s.day<=6&&validTime(s.time))&&new Set(c.slots.map(s=>s.day+s.time)).size===c.slots.length)&&x.exams.every((e,i)=>short(e.name)&&validDate(e.date)&&validDate(e.end)&&e.date<=e.end&&e.date>=x.termStart&&(!i||e.date>x.exams[i-1].end))&&x.events.every(e=>short(e.id)&&short(e.title)&&validDate(e.date)&&['off','extra'].includes(e.type)&&(e.classId==='all'||ids.includes(e.classId))&&(e.type!=='extra'||validTime(e.time)))&&new Set(x.events.map(e=>e.id)).size===x.events.length&&Object.entries(x.notes).every(([k,n])=>k.length<200&&n&&typeof n.content==='string'&&n.content.length<=2000&&typeof n.homework==='string'&&n.homework.length<=1000&&validDate(n.date)&&ids.includes(n.classId)&&validTime(n.time));}
let state=structuredClone(defaults), storageProblem=false;
try{const raw=globalThis.CloudConfig?null:localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validate(parsed))state=parsed;else storageProblem=true;}}catch{storageProblem=true;}
function taipeiNow(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const p=Object.fromEntries(parts.map(p=>[p.type,p.value]));return{date:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}`};}
function addDays(d,n){const date=new Date(d+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+n);return date.toISOString().slice(0,10)}
function weekday(d){return new Date(d+'T00:00:00Z').getUTCDay()}
function shortDate(d){return Number(d.slice(5,7))+'/'+Number(d.slice(8,10))}
const week=['日','一','二','三','四','五','六'];
let now=taipeiNow(),selectedDate=now.date,month=now.date.slice(0,7),examIndex=Math.max(0,state.exams.findIndex(e=>e.date>now.date)),filter='all',selectedClass=state.classes[0].id,listView=false,currentNote=null,draft=null,draftClass=null;
function examOn(d,data=state){return data.exams.find(e=>d>=e.date&&d<=e.end)}
function offEvents(d,c,data=state){return data.events.filter(e=>e.date===d&&e.type==='off'&&(e.classId==='all'||e.classId===c))}
function lessons(d,c='all',data=state,includeCancelled=false){let result=[];for(const cl of data.classes.filter(x=>c==='all'||x.id===c)){if(d>=data.termStart){for(const slot of cl.slots.filter(s=>s.day===weekday(d))){const cancelled=!!examOn(d,data)||offEvents(d,cl.id,data).length>0;if(!cancelled||includeCancelled)result.push({date:d,classId:cl.id,time:slot.time,key:`${d}_${cl.id}_${slot.time}`,cancelled,extra:false});}}for(const e of data.events.filter(e=>e.date===d&&e.type==='extra'&&(e.classId==='all'||e.classId===cl.id)))result.push({date:d,classId:cl.id,time:e.time,key:`${d}_${cl.id}_extra_${e.id}`,cancelled:false,extra:true,title:e.title});}return result.sort((a,b)=>a.time.localeCompare(b.time));}
function remaining(c,exam,data=state,at=taipeiNow()){let total=0,excluded=0,extra=0;for(let d=at.date>data.termStart?at.date:data.termStart;d<exam.date;d=addDays(d,1)){for(const l of lessons(d,c,data,true)){if(d===at.date&&l.time<=at.time)continue;if(l.cancelled)excluded++;else{total++;if(l.extra)extra++;}}}return{total,excluded,extra};}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('瀏覽器無法儲存，請立即匯出備份以免遺失。');return false;}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4500)}
function color(c){return c==='c2'?'purple':c==='c3'?'gold':''}
function clName(c){return state.classes.find(x=>x.id===c)?.name||c}
function options(all=true){return(all?'<option value="all">全部班級</option>':'')+state.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
function render(){now=taipeiNow();$('#clock').textContent=`${now.date.replaceAll('-',' / ')} · ${now.time} 臺北時間`;$('#examTabs').innerHTML=state.exams.map((e,i)=>`<button class="${i===examIndex?'active':''}" data-exam="${i}" aria-pressed="${i===examIndex}">${esc(e.name)}</button>`).join('');const exam=state.exams[examIndex];$('#cards').innerHTML=state.classes.map(c=>{const n=remaining(c.id,exam);return`<article class="card ${selectedClass===c.id?'selected':''}"><div class="row spread"><span class="class-name"><i class="dot"></i>${esc(c.name)}</span><span class="muted">${esc(c.subject)}</span></div><div class="count">${n.total}<small>堂課</small></div><div class="muted">${exam.date<=now.date?'此段考已開始或結束':'距離'+esc(exam.name)} · ${shortDate(exam.date)}</div><div class="card-bottom"><span>已排除 ${n.excluded} 堂停課</span><span>${n.extra?`含 ${n.extra} 堂補課`:`每週 ${c.slots.length} 堂`} ↗</span></div><button class="card-button" data-class="${c.id}" aria-label="查看${esc(c.name)}的課程"></button></article>`}).join('');$('#countInfo').textContent=`計算到 ${exam.date} 考試開始前，不含已開始的課；扣除假日、校內停課與其他段考。課表及段考為示範，可至設定修改。`;$('#classFilter').innerHTML=options();$('#classFilter').value=filter;renderCalendar();renderDetail();renderUpcoming();renderHistory();}
function renderCalendar(){const [y,m]=month.split('-').map(Number);$('#monthLabel').textContent=`${y} 年 ${m} 月`;$('#toggleList').textContent=listView?'月曆':'列表';const first=month+'-01',days=new Date(Date.UTC(y,m,0)).getUTCDate();if(listView){let html='';for(let i=0;i<days;i++){const d=addDays(first,i),ls=lessons(d,filter),events=state.events.filter(e=>e.date===d&&(filter==='all'||e.classId==='all'||e.classId===filter));if(ls.length||events.length||examOn(d))html+=`<div class="list-date ${d<now.date?'past':''}">${shortDate(d)} 週${week[weekday(d)]} ${examOn(d)?' · '+esc(examOn(d).name):''}</div>`+events.filter(e=>e.type==='off').map(e=>`<div class="list-lesson">${esc(e.title)} <span class="muted">停課</span></div>`).join('')+ls.map(l=>`<div class="list-lesson ${d<now.date?'past':''}"><span>${esc(clName(l.classId))}${l.extra?'（補課）':''}</span><button class="btn" data-note="${esc(l.key)}" data-date="${d}">${state.notes[l.key]?'檢視進度':'登記'}</button></div>`).join('');}$('#calendar').innerHTML=html||'<div class="empty">本月沒有課程或活動。</div>';return;}
const start=addDays(first,-((weekday(first)+6)%7));const cells=Math.ceil((((weekday(first)+6)%7)+days)/7)*7;let html='<div class="weekdays">'+['一','二','三','四','五','六','日'].map(x=>`<span>${x}</span>`).join('')+'</div><div class="grid">';for(let i=0;i<cells;i++){const d=addDays(start,i),ls=lessons(d,filter),ev=state.events.filter(e=>e.date===d&&e.type==='off'&&(filter==='all'||e.classId==='all'||e.classId===filter)),exam=examOn(d);const uniqueEvents=[...new Map(ev.map(e=>[e.title+(e.startTime||'')+(e.endTime||''),e])).values()];const badges=[...uniqueEvents.map(e=>`<span class="tag holiday" title="${esc(e.title)}">${esc(e.title)}</span>`),...(exam?[`<span class="tag exam">${esc(exam.name)}</span>`]:[]),...ls.map(l=>`<span class="tag ${color(l.classId)} ${state.notes[l.key]?'saved':''}">${state.notes[l.key]?'✓ ':''}${esc(clName(l.classId).replace('高一 ','').replace('高二 ',''))} ${l.extra?' 補':''}</span>`)];html+=`<button class="day ${d<now.date?'past':''} ${weekday(d)===0||weekday(d)===6?'weekend':''} ${!d.startsWith(month)?'out':''} ${d===now.date?'today':''} ${d===selectedDate?'chosen':''}" data-date="${d}" aria-label="${d}，${ls.length}堂課${ev.length?'，停課活動':''}" aria-pressed="${d===selectedDate}"><span class="day-number">${Number(d.slice(8))}</span>${badges.slice(0,3).join('')}${badges.length>3?`<span class="muted" style="font-size:10px">＋${badges.length-3} 項</span>`:''}</button>`;}$('#calendar').innerHTML=html+'</div>';}
function renderDetail(){const ls=lessons(selectedDate,filter),ev=state.events.filter(e=>e.date===selectedDate&&e.type==='off'&&(filter==='all'||e.classId==='all'||e.classId===filter)),exam=examOn(selectedDate);$('#detail').innerHTML=`<div class="detail-top"><div class="eyebrow">${selectedDate===now.date?'TODAY':'DAILY PLANNER'}</div><div class="detail-date">${shortDate(selectedDate)} <span style="font-size:15px;font-weight:400">星期${week[weekday(selectedDate)]}</span></div><div class="muted">${ls.length} 堂課 · ${ls.filter(l=>state.notes[l.key]).length} 堂已登記</div></div>${[...new Map(ev.map(e=>[e.title+(e.startTime||'')+(e.endTime||''),e])).values()].map(e=>`<p class="tag holiday" style="white-space:normal;margin-bottom:6px">${esc(e.title)}${e.classId!=='all'?' · '+esc(clName(e.classId)):''}</p>`).join('')}${exam?`<p class="tag exam">${esc(exam.name)} · 不計一般課程</p>`:''}${ls.map(l=>{const n=state.notes[l.key],cl=state.classes.find(c=>c.id===l.classId);return`<article class="lesson"><div class="lesson-head"><span class="muted">${l.time}${l.extra?' · 補課':''}</span><span class="status ${n?'done':''}">${n?'✓ 已登記':'待登記'}</span></div><h3><i class="dot"></i>${esc(cl.name)} <span class="muted">/ ${esc(cl.subject)}</span></h3><p>${n?esc(n.content):'這堂課，準備帶學生走到哪裡？'}</p>${n?.homework?`<p style="margin-top:7px">下次提醒：${esc(n.homework)}</p>`:''}<button class="btn ${n?'':'soft'}" data-note="${esc(l.key)}" data-date="${selectedDate}">${n?'編輯上課進度':'＋ 登記上課進度'}</button></article>`}).join('')}${!ls.length?'<div class="empty">今天沒有安排課程。<br>留點時間備課，也照顧自己。</div>':''}<button class="btn detail-add" data-add>＋ 加入這一天的活動</button>`;}
function renderUpcoming(){const upcoming=[...state.events.filter(e=>e.date>=now.date),...state.exams.filter(e=>e.end>=now.date).map(e=>({...e,title:e.name+'・示範／可編輯'}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);$('#upcoming').innerHTML='<h2>接下來的日子 <span style="float:right">↗</span></h2>'+upcoming.map(e=>`<div class="event-line"><span class="event-day">${shortDate(e.date)}</span><div>${esc(e.title)}<div class="muted" style="font-size:11px">${e.type==='extra'?'已計入補課堂數':'已納入堂數計算'}</div></div></div>`).join('')+(upcoming.length?'':'<p class="muted">目前沒有即將到來的活動。</p>');}
function renderHistory(){const entries=Object.entries(state.notes).filter(([k,n])=>filter==='all'||n.classId===filter).sort((a,b)=>(b[1].date+b[1].time).localeCompare(a[1].date+a[1].time));$('#history').innerHTML=`<div class="row spread"><h2>上課進度紀錄</h2><span class="muted">${filter==='all'?'全部班級':esc(clName(filter))} · ${entries.length} 筆</span></div>`+(entries.map(([k,n])=>`<article class="history-item"><div class="row spread"><div class="muted">${n.date} ${n.time} · ${esc(clName(n.classId))}</div><button class="btn" data-history-note="${esc(k)}">編輯</button></div><p>${esc(n.content)}</p>${n.homework?`<p class="muted">下次提醒：${esc(n.homework)}</p>`:''}</article>`).join('')||'<div class="empty">還沒有進度紀錄。<br>在行事曆選擇一堂課，寫下今天的進度吧。</div>');}
function changeView(history){$('#history').classList.toggle('hidden',!history);$('#calendarWorkspace').classList.toggle('hidden',history);$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===(history?'history':'calendar')));$('#historyView').classList.toggle('soft',history);$('#calendarView').classList.toggle('soft',!history)}
function openEvent(){const form=$('#eventForm');form.reset();form.elements.date.value=selectedDate;$('#eventClass').innerHTML=options();$('#extraField').classList.add('hidden');renderEventList();$('#eventDialog').showModal()}
function renderEventList(){$('#eventList').innerHTML=[...state.events].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="event-manage"><span>${e.date} · ${esc(e.title)}<br><span class="muted" style="font-size:11px">${e.classId==='all'?'全校':esc(clName(e.classId))} · ${e.type==='off'?'停課':'補課 '+e.time}</span></span><button type="button" class="btn" data-delete-event="${esc(e.id)}" aria-label="刪除${esc(e.title)}">刪除</button></div>`).join('')}
function openNote(l){currentNote=l;const n=state.notes[l.key];$('#noteMeta').textContent=`${l.date} ${l.time} · ${clName(l.classId)}`;$('#noteForm').elements.content.value=n?.content||'';$('#noteForm').elements.homework.value=n?.homework||'';$('#deleteNote').classList.toggle('hidden',!n);$('#noteDialog').showModal();}
function collectClass(){const c=draft.classes.find(c=>c.id===draftClass);c.name=$('#className').value.trim();c.subject=$('#subjectName').value.trim();c.slots=$$('.schedule-row').map(r=>({day:Number(r.querySelector('select').value),time:r.querySelector('input').value}));}
function showClass(){const c=draft.classes.find(c=>c.id===draftClass);$('#className').value=c.name;$('#subjectName').value=c.subject;$('#scheduleRows').innerHTML=c.slots.map((s,i)=>`<div class="schedule-row"><select aria-label="星期">${[1,2,3,4,5,6,0].map(d=>`<option value="${d}" ${d===s.day?'selected':''}>星期${week[d]}</option>`).join('')}</select><input type="time" value="${s.time}" required aria-label="上課時間"><button type="button" class="btn" data-delete-slot="${i}" aria-label="移除此堂課">×</button></div>`).join('')}
function openSettings(){draft=structuredClone(state);draftClass=state.classes[0].id;$('#termStart').value=state.termStart;$('#termEnd').value=state.termEnd;$('#examSettings').innerHTML=state.exams.map((e,i)=>`<div class="exam-row"><label>${esc(e.name)}・開始<input type="date" data-exam-start="${i}" value="${e.date}" required></label><label>結束<input type="date" data-exam-end="${i}" value="${e.end}" required></label></div>`).join('');$('#scheduleClass').innerHTML=options(false);showClass();$('#settingsDialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if('close'in d)b.closest('dialog').close();if(d.exam!==undefined){examIndex=Number(d.exam);render()}if(d.class){selectedClass=d.class;filter=d.class;render()}if(d.date&&!d.note){selectedDate=d.date;renderCalendar();renderDetail()}if(d.note){const l=lessons(d.date).find(l=>l.key===d.note);if(l)openNote(l)}if(d.historyNote){openNote({...state.notes[d.historyNote],key:d.historyNote})}if('add'in d)openEvent();if(d.nav){if(d.nav==='settings')openSettings();else changeView(d.nav==='history')}if(d.deleteEvent){if(confirm('刪除此活動？刪除後會重新計算堂數。')){state.events=state.events.filter(x=>x.id!==d.deleteEvent);save();renderEventList();render()}}if(d.deleteSlot!==undefined){collectClass();draft.classes.find(c=>c.id===draftClass).slots.splice(Number(d.deleteSlot),1);showClass()}});
$('#addEvent').onclick=openEvent;$('#settings').onclick=openSettings;$('#calendarView').onclick=()=>changeView(false);$('#historyView').onclick=()=>changeView(true);
function shiftMonth(n){const [y,m]=month.split('-').map(Number);month=new Date(Date.UTC(y,m-1+n,1)).toISOString().slice(0,7);renderCalendar()}
$('#prev').onclick=()=>shiftMonth(-1);$('#next').onclick=()=>shiftMonth(1);$('#today').onclick=()=>{selectedDate=taipeiNow().date;month=selectedDate.slice(0,7);render()};$('#toggleList').onclick=()=>{listView=!listView;renderCalendar()};$('#classFilter').onchange=e=>{filter=e.target.value;renderCalendar();renderDetail();renderHistory()};
$('#eventForm').elements.type.onchange=e=>$('#extraField').classList.toggle('hidden',e.target.value!=='extra');
$('#eventForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),event={id:'e'+Date.now()+Math.random().toString(36).slice(2,7),title:f.get('title').trim(),date:f.get('date'),type:f.get('type'),classId:f.get('classId'),time:f.get('time')};if(!event.title||!validDate(event.date)||(event.type==='extra'&&!validTime(event.time))){toast('請填寫有效的名稱、日期與時間。');return}state.events.push(event);const ok=save();$('#eventDialog').close();render();if(ok)toast('活動已儲存，剩餘堂數已更新。')};
$('#noteForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),content=f.get('content').trim();if(!content){toast('請填寫本堂課的進度。');return}state.notes[currentNote.key]={date:currentNote.date,classId:currentNote.classId,time:currentNote.time,content,homework:f.get('homework').trim()};const ok=save();$('#noteDialog').close();render();if(ok)toast('已記下這一堂課的進度。')};
$('#deleteNote').onclick=()=>{if(confirm('刪除此堂課的進度紀錄？')){delete state.notes[currentNote.key];save();$('#noteDialog').close();render()}};
$('#scheduleClass').onchange=e=>{collectClass();draftClass=e.target.value;showClass()};$('#addSlot').onclick=()=>{collectClass();draft.classes.find(c=>c.id===draftClass).slots.push({day:1,time:'08:10'});showClass()};
$('#settingsForm').onsubmit=e=>{e.preventDefault();collectClass();draft.termStart=$('#termStart').value;draft.termEnd=$('#termEnd').value;draft.exams.forEach((x,i)=>{x.date=$(`[data-exam-start="${i}"]`).value;x.end=$(`[data-exam-end="${i}"]`).value});draft.notes=state.notes;draft.events=state.events;if(!validate(draft)){toast('請確認班級名稱、日期先後與課表；段考不可重疊，課表不可重複。');return}state=draft;const ok=save();$('#settingsDialog').close();render();if(ok)toast('課表與段考設定已更新。')};
$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`課日備份-${taipeiNow().date}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('備份已匯出（使用目前已套用的設定）。')};
$('#importData').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error();const next=JSON.parse(await file.text());if(!validate(next))throw Error();if(confirm('還原會取代目前的課表、活動與進度，確定還原？')){state=next;const ok=save();$('#settingsDialog').close();render();if(ok)toast('備份已還原。')}}catch{toast('無法讀取備份，請選擇此網站匯出的有效 JSON 檔案。')}finally{e.target.value=''}};
